from pathlib import Path
import json,html
P=Path(__file__).resolve().parent;ROOT=P.parents[2];registry=json.loads((P/'animation-deliveries.json').read_text())
ids=['hanging-pots','garden-shears'];data={};sections=[]
for eid in ids:
 d=P/registry[eid]['staging'];index=json.loads((d/'index.json').read_text());prod=json.loads((d/'production-manifest.json').read_text());data[eid]=index
 sections.append('<h2>'+html.escape(eid.replace('-',' ').title())+'</h2><p>'+html.escape(prod['method'])+'</p>')
 for state,m in index['clips'].items():
  sections.append('<h3>'+state.title()+' — '+str(m['frames'])+' frames / '+str(m['frames']/30)+' s</h3><p>'+html.escape(prod['actions'][state])+'</p><img class="contact" src="'+registry[eid]['staging']+'/'+state+'-contact.jpg" alt="Chronological '+eid+' '+state+' poses"><p><a href="'+registry[eid]['staging']+'/'+state+'-preview.webp">Animated WebP</a> · <a href="../../../animations/sprites/enemies/animations/'+m['source']+'">Source PNG sheet</a> · <a href="../../../game/assets/sprites/enemy-clips/'+eid+'/'+m['file']+'">Runtime atlas</a></p>')
 sections.append('<p><a href="'+registry[eid]['validation']+'">Technical validation</a> · <a href="'+registry[eid]['receipt']+'">Saved paths and hashes</a></p>')
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Batch 03 — 30 fps enemy clips</title><style>body{font:16px/1.5 system-ui;background:#20212b;color:#eceaf4;max-width:1150px;margin:24px auto;padding:20px}a{color:#bdcfff}canvas{display:block;width:384px;max-width:100%;height:auto;background:repeating-conic-gradient(#292a35 0% 25%,#353643 0% 50%) 0/24px 24px;border:1px solid #74758a}button,select,input{font:inherit;padding:8px;margin:5px}.contact{width:100%;height:auto}.notice{border-left:3px solid #b1a3e8;padding:14px;background:#292b38}input[type=range]{width:360px;max-width:90%}</style><p><a href="animation-gallery.html">Full enemy/action matrix</a> · <a href="hall-mirror-preview.html">Corrected Hall Mirror</a></p><h1>Hanging Pots and Garden Shears</h1><p class="notice">Eight saved clips at 30 fps. Per-frame decoding, packing, attachment pivot, changing frames, loop/endpoint and duration checks passed. Character-specific source-art rigs; not fully redrawn animation. Full-speed intended-size visual review is pending. Browser URL-policy denial was respected; no browser playback or game integration is claimed.</p><label>Enemy <select id="enemy"><option value="hanging-pots">Hanging Pots</option><option value="garden-shears">Garden Shears</option></select></label><label>Action <select id="action"><option>idle</option><option>attack</option><option>hurt</option><option>defeat</option></select></label><canvas width="384" height="384" aria-label="Enemy animation preview"></canvas><p><button id="play">Pause</button><button id="replay">Replay</button><button id="step">Next frame</button></p><input id="scrub" type="range" min="0" max="59" value="0" aria-label="Frame"><p id="status">Loading local atlas…</p><p>Idle loops. One-shots stop at their final pose for inspection; defeat holds its inactive object. Source cells are 512 × 512 and runtime cells 384 × 384. The clock uses 1000/30 ms per frame; animated WebPs alternate 33/34 ms durations.</p>__SECTIONS__<script>const data=__DATA__,canvas=document.querySelector('canvas'),ctx=canvas.getContext('2d'),enemy=document.querySelector('#enemy'),action=document.querySelector('#action'),scrub=document.querySelector('#scrub'),status=document.querySelector('#status'),play=document.querySelector('#play'),cache=new Map();let frame=0,playing=!matchMedia('(prefers-reduced-motion: reduce)').matches,origin=null;function meta(){return data[enemy.value].clips[action.value]}function atlas(){const key=enemy.value+'/'+action.value;if(!cache.has(key)){const im=new Image();im.onload=draw;im.onerror=()=>{status.textContent='Unable to load '+key};im.src='../../../game/assets/sprites/enemy-clips/'+enemy.value+'/'+meta().file;cache.set(key,im)}return cache.get(key)}function draw(){const m=meta(),im=atlas();if(!im.complete||!im.naturalWidth)return;ctx.clearRect(0,0,384,384);ctx.drawImage(im,frame%m.cols*m.fw,Math.floor(frame/m.cols)*m.fh,m.fw,m.fh,0,0,384,384);scrub.max=m.frames-1;scrub.value=frame;status.textContent=enemy.value+' / '+action.value+' — frame '+(frame+1)+' of '+m.frames+' · 30 fps'+(!playing?' · paused/held':'');play.textContent=playing?'Pause':'Play'}function restart(){frame=0;origin=null;playing=true;draw()}enemy.onchange=restart;action.onchange=restart;document.querySelector('#replay').onclick=restart;play.onclick=()=>{if(!meta().loop&&frame===meta().frames-1)frame=0;playing=!playing;origin=null;draw()};document.querySelector('#step').onclick=()=>{playing=false;origin=null;frame=Math.min(frame+1,meta().frames-1);draw()};scrub.oninput=()=>{playing=false;origin=null;frame=Number(scrub.value);draw()};function tick(t){if(playing){if(origin===null)origin=t-frame*1000/30;const m=meta(),raw=Math.floor((t-origin)*30/1000),next=m.loop?raw%m.frames:Math.min(raw,m.frames-1);if(!m.loop&&raw>=m.frames){playing=false;origin=null}if(next!==frame){frame=next;draw()}else if(!playing)draw()}requestAnimationFrame(tick)}draw();requestAnimationFrame(tick);</script></html>'''.replace('__SECTIONS__',''.join(sections)).replace('__DATA__',json.dumps(data))
(P/'batch-03-preview.html').write_text(page,encoding='utf-8');print('Batch 03 preview saved')
